/*
 * mtp-smp — the µOS++ SMP scheduler on every core of this board, tested
 * with µTest++ (micro-test-plus).
 * GENERATED by micro-os-scaffold (--micro-test-plus), for the boards whose
 * other cores the board support can release (MTP_HAS_SMP_BOOT).
 *
 *   00 - Cores             the other cores joined the scheduler
 *   01 - Affinity          a pinned thread runs on its core; affinity changes
 *   02 - Critical sections interrupts::critical_section excludes all cores,
 *                          masks and restores this core's IRQs, nests;
 *                          scheduler::critical_section is local to its core
 *   03 - Spinlocks         a cross-core spinlock: no lost update, try_lock
 *   04 - Mutexes           contention from all cores, timed_lock, recursive,
 *                          priority inheritance across cores
 *   05 - Scheduler         preemption, yield between equal priorities, every
 *                          core busy at once, the load spread over the cores
 *   06 - Cross-core sync   semaphore ping-pong, message queue, event flags,
 *                          a barrier of all cores
 *   07 - Queue stress      one producer per core into one bounded queue
 *   08 - Atomic RMW        mtp_board::atomic_add () from every core, through
 *                          the board's method (sync_method (): the exclusive
 *                          monitor on the Raspberry Pi cores, an SIO hardware
 *                          spinlock on the RP2040/RP2350); plain std::atomic
 *                          too, except on the RP2040/RP2350, whose exclusive
 *                          monitor does not serialise the two cores
 *   09 - Speed-up          the same CPU-bound work on one core, then on every
 *                          core at once: at least 0.8 x OS_NCPU faster on the
 *                          board (reported only under QEMU)
 *
 * Spinlocks and atomic_add () use the board's method, named in the report.
 *
 * The runner stays on core 0 (release_cores () pins it there); every check
 * is written for OS_NCPU cores.
 */
#include <mtp_board.hpp>

#include <cstdio>

#if !defined(MTP_HAS_SMP_BOOT) || !MTP_HAS_SMP_BOOT || OS_NCPU < 2
#error "mtp-smp needs a multi-core build with the board's SMP boot helpers"
#endif

// Each suite lives in its own suite-*.cpp file and registers itself; there
// is no list here to keep in step with them.

int
os_main (int argc, char* argv[])
{
  mtp_board::start ("mtp-smp");
  mtp_board::release_cores ();
  std::printf ("# cross-core sync method: %s\n", mtp_board::sync_method ());
  return mtp_board::run (argc, argv);
}

#include <mtp_startup.hpp>
